-- Intercepta e traduz os argumentos no ponto de entrada
local args = normalizarArgumentos(frame.args)

local image = args["image"];

if isempty(image) then
    return "";
end
if image == "&nbsp;" then
    return image;
end
if args["suppressplaceholder"] ~= "no" then
    if i.IsPlaceholder(image) == true then
        return "";
    end
end

if string.find(image, "^%[*https?:") then
    -- Error category.
    return trackingCat("url_image_links")
end

if mw.ustring.sub(image,1,2) == "[[" then
    -- search for thumbnail images and add to tracking cat if found
    local cat = "";
    if mw.title.getCurrentTitle().namespace == 0 and (mw.ustring.find(image, "|%s*thumb%s*[|%]]") or mw.ustring.find(image, "|%s*thumbnail%s*[|%]]")) then
        cat = trackingCat("thumbnail_images")
    end
    return image .. cat;
elseif mw.ustring.sub(image,1,2) == "{{" and mw.ustring.sub(image,1,3) ~= "{{{" then
    return image;
elseif mw.ustring.sub(image,1,1) == "<" then
    return image;
elseif mw.ustring.sub(image,1,8) == mw.ustring.char(127).."'\"`UNIQ" then
    -- Found strip marker at begining, so pass don't process at all
    return image;
